// ---- Wide-bus helper functions (self-contained) ----
// Read 'num' float/double elements starting at byte offset 'offset' from a
// wide-bus pointer 'in' into local buffer 'out'.
template <typename T, int W>
static void memcpy_wide_bus_read_float(T *out, MARS_WIDE_BUS_TYPE *in,
                                       long offset, int num)
{
    const int elem_bits = sizeof(T) * 8;
    const int per_word = W / elem_bits;          // elements per wide word
    long base_elem = offset / (long)sizeof(T);   // starting element index

    read_loop: for (int n = 0; n < num; n++) {
#pragma HLS LOOP_TRIPCOUNT min=1 max=TILE
#pragma HLS PIPELINE II=1
        long ge = base_elem + n;                 // global element index
        long word = ge / per_word;               // which wide word
        int sub = (int)(ge % per_word);          // position within word
        MARS_WIDE_BUS_TYPE w = in[word];
        ap_uint<elem_bits> bits =
            w.range((sub + 1) * elem_bits - 1, sub * elem_bits);
        union { ap_uint<elem_bits> u; T v; } cvt;
        cvt.u = bits;
        out[n] = cvt.v;
    }
}

// Write 'num' float/double elements from local buffer 'in' into wide-bus
// pointer 'out' starting at byte offset 'offset'.
template <typename T, int W>
static void memcpy_wide_bus_write_float(MARS_WIDE_BUS_TYPE *out, T *in,
                                        long offset, int num)
{
    const int elem_bits = sizeof(T) * 8;
    const int per_word = W / elem_bits;
    long base_elem = offset / (long)sizeof(T);

    write_loop: for (int n = 0; n < num; n++) {
#pragma HLS LOOP_TRIPCOUNT min=1 max=TILE
#pragma HLS PIPELINE II=1
        long ge = base_elem + n;
        long word = ge / per_word;
        int sub = (int)(ge % per_word);
        union { ap_uint<elem_bits> u; T v; } cvt;
        cvt.v = in[n];
        MARS_WIDE_BUS_TYPE w = out[word];
        w.range((sub + 1) * elem_bits - 1, sub * elem_bits) = cvt.u;
        out[word] = w;
    }
}

